"""guard_header_macros wraps a header in a consumer-macro guard.

The guard saves, removes and afterwards restores every macro that could
change the header's meaning: exactly the identifiers the header uses that a
consumer is entitled to define (tools/consumer_macros.py says which).

    /* consumer-macro guard: generated by tools/guard_header_macros.py; do not edit */
    #pragma push_macro("near")
    #undef near
    ...
    /* consumer-macro guard end */
      (the header's own text)
    /* consumer-macro restore: generated by tools/guard_header_macros.py; do not edit */
    #pragma pop_macro("near")
    ...
    /* consumer-macro restore end */

The opening block goes after #pragma once (or after an include guard's
#define), so a header included twice costs nothing the second time; the
closing block goes at the end (or before the include guard's #endif). A
consumer's macro is therefore absent while the header is read and back,
unchanged, after it. push_macro and pop_macro are accepted by Clang, GCC
and MSVC, in C as in C++.

Rerunning replaces an existing guard, so the output depends only on the
header's own text. Macros the header or its first-party includes define
are never guarded (popping them would delete them); names read only in #if
lines are configuration inputs and are left alone too.

    python3 -B tools/guard_header_macros.py HEADER --include-root include \\
        --standard-names tests/hostile_macros/standard_library_names.txt \\
        [--output PATH | --in-place | --check]

Without --output or --in-place the guarded text goes to standard output.
--check exits 1 when the header's guard is missing or out of date.
"""
from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

import consumer_macros

GUARD_BEGIN: str = '/* consumer-macro guard: generated by tools/guard_header_macros.py; do not edit */'
GUARD_END: str = '/* consumer-macro guard end */'
RESTORE_BEGIN: str = '/* consumer-macro restore: generated by tools/guard_header_macros.py; do not edit */'
RESTORE_END: str = '/* consumer-macro restore end */'

PRAGMA_ONCE = re.compile(r'^[ \t]*#[ \t]*pragma[ \t]+once\b[^\n]*\n?', re.MULTILINE)
DIRECTIVE = re.compile(r'^[ \t]*#[ \t]*(\w+)[ \t]*(\w*)', re.MULTILINE)


def remove_guard(text: str) -> str:
    """The header without any guard this tool inserted earlier."""
    for begin, end in ((GUARD_BEGIN, GUARD_END), (RESTORE_BEGIN, RESTORE_END)):
        start: int = text.find(begin)
        while start >= 0:
            stop: int = text.find(end, start)
            if stop < 0:
                raise SystemExit(f'unterminated guard block starting "{begin}"')
            stop += len(end)
            if text.startswith('\n', stop):
                stop += 1
            text = text[:start] + text[stop:]
            start = text.find(begin)
    return text


def insertion_points(text: str) -> tuple[int, int]:
    """Offsets for the opening and closing blocks.

    After #pragma once and at the end; else inside a leading include guard
    (#ifndef X, #define X, ..., final #endif); else at the start and end.
    Only directives are examined, so a comment that mentions #pragma once
    does not count (comments are blanked first).
    """
    code: str = blank_comments(text)
    once: re.Match[str] | None = PRAGMA_ONCE.search(code)
    if once:
        return once.end(), len(text)
    directives: list[re.Match[str]] = list(DIRECTIVE.finditer(code))
    if len(directives) >= 3:
        first: re.Match[str] = directives[0]
        second: re.Match[str] = directives[1]
        last: re.Match[str] = directives[-1]
        if (first.group(1) == 'ifndef' and second.group(1) == 'define' and second.group(2) == first.group(2)
                and last.group(1) == 'endif'):
            line_end: int = code.find('\n', second.end())
            opening: int = len(text) if line_end < 0 else line_end + 1
            return opening, last.start()
    return 0, len(text)


def blank_comments(text: str) -> str:
    """text with comments replaced by spaces, newlines and offsets kept."""
    output: list[str] = []
    index: int = 0
    length: int = len(text)
    while index < length:
        if text.startswith('//', index):
            end: int = text.find('\n', index)
            end = length if end < 0 else end
            output.append(' ' * (end - index))
            index = end
        elif text.startswith('/*', index):
            end = text.find('*/', index + 2)
            end = length if end < 0 else end + 2
            output.append(re.sub(r'[^\n]', ' ', text[index:end]))
            index = end
        elif text[index] in '"\'':
            quote: str = text[index]
            end = index + 1
            while end < length and text[end] != quote and text[end] != '\n':
                end += 2 if text[end] == '\\' else 1
            end = min(end + 1, length)
            output.append(text[index:end])
            index = end
        else:
            output.append(text[index])
            index += 1
    return ''.join(output)


def guarded_names(header: Path, text: str, roots: list[Path], standard_names: frozenset[str]) -> list[str]:
    """The identifiers to guard in header, whose unguarded text is text."""
    scan: consumer_macros.HeaderScan = consumer_macros.scan_header(text)
    closure: consumer_macros.Closure = consumer_macros.compute_closure(scan.includes, roots, header.parent)
    included_macros: set[str] = set()
    for nested in closure.headers.values():
        included_macros |= nested.defined
    classification: consumer_macros.Classification = consumer_macros.classify(
        {header: scan}, standard_names, first_party_macros=included_macros)
    return sorted(classification.hostile)


def guard_text(text: str, names: list[str]) -> str:
    """text (unguarded) with the guard for names inserted; text if names is empty."""
    if not names:
        return text
    opening, closing = insertion_points(text)
    save: list[str] = [GUARD_BEGIN]
    for name in names:
        save.append(f'#pragma push_macro("{name}")')
        save.append(f'#undef {name}')
    save.append(GUARD_END)
    restore: list[str] = [RESTORE_BEGIN]
    for name in reversed(names):
        restore.append(f'#pragma pop_macro("{name}")')
    restore.append(RESTORE_END)
    before: str = text[:opening]
    middle: str = text[opening:closing]
    after: str = text[closing:]
    if before and not before.endswith('\n'):
        before += '\n'
    if middle and not middle.endswith('\n'):
        middle += '\n'
    return before + '\n'.join(save) + '\n' + middle + '\n'.join(restore) + '\n' + after


def guard_header(header: Path, roots: list[Path], standard_names: frozenset[str]) -> str:
    """The guarded text of header."""
    text: str = remove_guard(consumer_macros.read_source(header))
    return guard_text(text, guarded_names(header.resolve(), text, roots, standard_names))


def main(argument_list: list[str]) -> int:
    parser: argparse.ArgumentParser = argparse.ArgumentParser(description=__doc__.split('\n')[0])
    parser.add_argument('header', type=Path)
    parser.add_argument('--include-root', action='append', default=[])
    parser.add_argument('--standard-names', type=Path, required=True)
    destination = parser.add_mutually_exclusive_group()
    destination.add_argument('--output', type=Path)
    destination.add_argument('--in-place', action='store_true')
    destination.add_argument('--check', action='store_true')
    arguments: argparse.Namespace = parser.parse_args(argument_list)

    roots: list[Path] = [Path(root).resolve() for root in arguments.include_root]
    standard_names: frozenset[str] = consumer_macros.load_standard_names(arguments.standard_names)
    guarded: str = guard_header(arguments.header, roots, standard_names)
    if arguments.check:
        current: str = consumer_macros.read_source(arguments.header)
        if current != guarded:
            print(f'{arguments.header}: consumer-macro guard missing or out of date', file=sys.stderr)
            return 1
        return 0
    if arguments.in_place:
        arguments.header.write_text(guarded, encoding='utf-8')
    elif arguments.output:
        arguments.output.parent.mkdir(parents=True, exist_ok=True)
        arguments.output.write_text(guarded, encoding='utf-8')
    else:
        sys.stdout.write(guarded)
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
